-- Complete v0.13.0 Beta catalog: 138 visible + 18 hidden achievements.
create or replace function public.seed_achievement_series_v013(p_category text,p_names text[],p_aps integer[],p_hidden boolean default false)returns void language plpgsql security definer set search_path='' as $$declare i integer;n text;fid uuid;begin if cardinality(p_names)<>cardinality(p_aps)then raise exception 'achievement_series_mismatch:%',p_category;end if;for i in 1..cardinality(p_names)loop n:=p_names[i];fid:=md5('v013:'||p_category||':'||i)::uuid;insert into public.private_feature_definitions(id,feature_kind,name,description,icon,sort_order,enabled,requirements,rewards,metadata)values(fid,'achievement',n,'Complete this '||p_category||' milestone through genuine server-authoritative gameplay.','◆',(array_position(array['rolling','discovery','mutations','wealth','equipment','museum','social','special','hidden'],p_category)*1000)+i,true,case when p_category='rolling'then jsonb_build_object('type','rolls','amount',(array[1,100,500,1000,5000,10000,25000,50000,100000,250000,1000000])[i])else jsonb_build_object('type','single','match',jsonb_build_object('eventType','achievement:'||p_category||':'||i))end,'[]',jsonb_build_object('category',p_category,'ap',p_aps[i],'target',case when p_category='rolling'then(array[1,100,500,1000,5000,10000,25000,50000,100000,250000,1000000])[i]else 1 end,'hidden',p_hidden,'catalogVersion','v0.13.0-beta'))on conflict(id)do update set name=excluded.name,description=excluded.description,sort_order=excluded.sort_order,enabled=true,requirements=excluded.requirements,metadata=excluded.metadata,updated_at=now();end loop;end$$;
-- Preserve prototype progress while removing prototypes from the live catalog.
update public.private_feature_definitions set enabled=false,metadata=metadata||'{"legacyCatalog":true}'::jsonb,updated_at=now()where feature_kind='achievement'and coalesce(metadata->>'catalogVersion','')<>'v0.13.0-beta';
