do $$declare vc integer;hc integer;va integer;ta integer;begin select count(*)filter(where not coalesce((metadata->>'hidden')::boolean,false)),count(*)filter(where coalesce((metadata->>'hidden')::boolean,false)),sum((metadata->>'ap')::integer)filter(where not coalesce((metadata->>'hidden')::boolean,false)),sum((metadata->>'ap')::integer)into vc,hc,va,ta from public.private_feature_definitions where feature_kind='achievement'and metadata->>'catalogVersion'='v0.13.0-beta';if vc<>138 or hc<>18 or va<>10145 or ta<>11565 then raise exception 'achievement_catalog_validation_failed visible=% hidden=% visible_ap=% total_ap=%',vc,hc,va,ta;end if;end$$;
revoke all on function public.seed_achievement_series_v013(text,text[],integer[],boolean)from public,anon,authenticated;grant execute on function public.seed_achievement_series_v013(text,text[],integer[],boolean)to service_role;
